%[text] Step 1: Create Trapezoidal Velocity Trajectories
clear all;
close all;
clc;

%% 1) Cargar puntos desde CSV (en pixeles)
points = readmatrix('points.csv');   % columnas: [x_pix, y_pix]
x_pix = points(:,1);
y_pix = points(:,2);

% Invertir eje y (imagen -> plano cartesiano)
y_pix = -y_pix;

%% 2) Usar el PRIMER punto como origen -> inicio en (0,0)
x0 = x_pix - x_pix(1);
y0 = y_pix - y_pix(1);

% Escalar para que quepa en |x|,|y| <= 0.16 (dejamos margen 0.14)
max_abs = max([abs(x0); abs(y0)]);
scale   = 0.14 / max_abs;

xd_raw = scale * x0;
yd_raw = scale * y0;

% Cerrar trayectoria (último punto = primero = (0,0))
xd_raw(end+1) = xd_raw(1);
yd_raw(end+1) = yd_raw(1);

%% 3) Re-muestrear a lo largo de la longitud de arco (suaviza la velocidad)
%    - calculamos longitud acumulada s
Nraw = numel(xd_raw);
s = zeros(Nraw,1);
for i = 2:Nraw
    dx = xd_raw(i) - xd_raw(i-1);
    dy = yd_raw(i) - yd_raw(i-1);
    s(i) = s(i-1) + sqrt(dx^2 + dy^2);
end
L = s(end);   % longitud total

% Queremos muchos puntos suaves, por ejemplo 1000:
Ngeom = 15000;
s_uniform = linspace(0, L, Ngeom);

xd_geom = interp1(s, xd_raw, s_uniform, 'linear');
yd_geom = interp1(s, yd_raw, s_uniform, 'linear');

% Asegurar que inicio y final son exactamente (0,0)
xd_geom = xd_geom - xd_geom(1);
yd_geom = yd_geom - yd_geom(1);
xd_geom(end) = 0;
yd_geom(end) = 0;

%% 4) Comprobaciones en el espacio geométrico
fprintf('max |x| = %.3f, max |y| = %.3f\n', max(abs(xd_geom)), max(abs(yd_geom))); %[output:7e3f15eb]
fprintf('Initial Geometric: (%.3f, %.3f)\n', xd_geom(1), yd_geom(1)); %[output:9d490504]
fprintf('Final Geometric:   (%.3f, %.3f)\n', xd_geom(end), yd_geom(end)); %[output:00803414]
fprintf('Arc length L = %.4f m\n', L); %[output:2f829417]

figure; %[output:47a094cc]
plot(xd_geom, yd_geom, 'k-','LineWidth',1.5); %[output:47a094cc]
axis equal; grid on; %[output:47a094cc]
title('Trayectoria geométrica re-muestreada en \{b\}'); %[output:47a094cc]
xlabel('x [m]'); ylabel('y [m]'); %[output:47a094cc]

%% 5) Parámetros de tiempo y velocidad promedio
tfinal = 25;      % Aumenté un poco el tiempo para hacerla aún más suave
dt     = 0.002;
t      = 0:dt:tfinal;
ta     = 0.2 * tfinal;   % 20% acel/freno

c = L / tfinal;          % velocidad promedio
fprintf('Average speed c = %.4f m/s\n', c); %[output:66b932d9]

% Perfil trapezoidal normalizado
g = @(t, T, ta) (T/(T-ta))*((t < ta) .* (t / ta) + ...
                            (t >= ta & t <= (T - ta)) .* 1 + ...
                            (t > (T - ta)) .* ((T - t) / ta));

%% 6) Reparametrización con alpha(t)
T_path = 1;                      % alpha en [0,1]
alpha  = zeros(size(t));         % alpha(0) = 0

alpha_table = linspace(0, 1, Ngeom);
dx_dalpha   = gradient(xd_geom, alpha_table);
dy_dalpha   = gradient(yd_geom, alpha_table);

for i = 1:length(t)-1
    % derivada geométrica respecto a alpha
    xdot = interp1(alpha_table, dx_dalpha, alpha(i), 'linear', 'extrap');
    ydot = interp1(alpha_table, dy_dalpha, alpha(i), 'linear', 'extrap');
    s_geom = sqrt(xdot^2 + ydot^2);
    s_geom = max(s_geom, 1e-5);        % un poco mayor para evitar picos

    v_des   = c * g(t(i), tfinal, ta); % velocidad deseada

    alpha_dot = v_des / s_geom;
    alpha(i+1) = alpha(i) + alpha_dot * dt;
end

% Normalizar para que alpha(tfinal) llegue exactamente a 1
alpha = alpha * (T_path / alpha(end));

%% 7) Trayectoria con escalamiento temporal
x_traj = interp1(alpha_table, xd_geom, alpha, 'linear', 'extrap');
y_traj = interp1(alpha_table, yd_geom, alpha, 'linear', 'extrap');

% Forzar que empiece y termine EXACTAMENTE en (0,0)
x_traj = x_traj - x_traj(1);
y_traj = y_traj - y_traj(1);
x_traj(end) = 0;
y_traj(end) = 0;

fprintf('real start: (%.3f, %.3f)\n', x_traj(1), y_traj(1)); %[output:2c28cb40]
fprintf('real final: (%.3f, %.3f)\n', x_traj(end), y_traj(end)); %[output:45f85800]

figure; %[output:17860370]
plot(x_traj, y_traj, 'LineWidth', 1.5); %[output:17860370]
axis equal; grid on; %[output:17860370]
xlabel('x [m]'); ylabel('y [m]'); %[output:17860370]
title('Trayectoria del robot con escalamiento temporal'); %[output:17860370]

%% 8) Plot de alpha(t)
figure; %[output:85b8ae59]
plot(t, alpha, 'LineWidth', 2); %[output:85b8ae59]
grid on; %[output:85b8ae59]
xlabel('time (s)'); %[output:85b8ae59]
ylabel('\alpha(t)'); %[output:85b8ae59]
title('Plot of \alpha(t)'); %[output:85b8ae59]
yline(T_path, 'k--', 'LineWidth', 2); %[output:85b8ae59]
legend('\alpha', 'T (period)', 'Location', 'southeast'); %[output:85b8ae59]

%% 9) Velocidad v[k] y verificación del límite
vx = diff(x_traj) / dt;
vy = diff(y_traj) / dt;
v  = sqrt(vx.^2 + vy.^2);
t_v = t(2:end);

fprintf('Max velocity (simulated) = %.4f m/s\n', max(v)); %[output:9abd81f1]

figure; %[output:8b765c54]
plot(t_v, v, 'LineWidth', 3); hold on; %[output:8b765c54]
yline(c,    'k--', 'c (average velocity)'); %[output:8b765c54]
yline(0.25,'r--', '0.25 m/s'); %[output:8b765c54]
ylim([0 0.3]); %[output:8b765c54]
grid on; %[output:8b765c54]
title('Trajectory Velocity'); %[output:8b765c54]
xlabel('time (s)'); %[output:8b765c54]
ylabel('velocity v[k] (m/s)'); %[output:8b765c54]
legend('velocity', 'average velocity', 'velocity limit', ... %[output:8b765c54]
       'Location', 'southoutside', 'Orientation', 'horizontal'); %[output:8b765c54]
hold off; %[output:8b765c54]
%%
%[text] ## Step 2: Forward Kinematics
%[text] (2c) Calculate T0
%% STEP 2: Forward Kinematics

% (2c) Calculate T0 (igual que en el enunciado)

L1 = 0.2435;
L2 = 0.2132;
W1 = 0.1311;
W2 = 0.0921;
H1 = 0.1519;
H2 = 0.0854;

% home position of end effector
M = [-1 0 0 L1+L2;
      0 0 1 W1+W2;
      0 1 0 H1-H2;
      0 0 0 1];

% screw axes (space)
S1 = [0 0 1 0 0 0]';
S2 = [0 1 0 -H1 0 0]';
S3 = [0 1 0 -H1 0 L1]';
S4 = [0 1 0 -H1 0 L1+L2]';
S5 = [0 0 -1 -W1 L1+L2 0]';
S6 = [0 1 0 H2-H1 0 L1+L2]';
S  = [S1 S2 S3 S4 S5 S6];

% body screw axes
B1 = ECE569_Adjoint(M)\S1;
B2 = ECE569_Adjoint(M)\S2;
B3 = ECE569_Adjoint(M)\S3;
B4 = ECE569_Adjoint(M)\S4;
B5 = ECE569_Adjoint(M)\S5;
B6 = ECE569_Adjoint(M)\S6;
B  = [B1 B2 B3 B4 B5 B6];

% joint angles (config inicial)
theta0 = [-1.6800   -1.4018   -1.8127   -2.9937   -0.8857   -0.0696]';

% T_sb(0)
T0_space = ECE569_FKinSpace(M,S,theta0) %[output:1fa355bf]
T0_body  = ECE569_FKinBody(M,B,theta0) %[output:4b2416db]
T0_space - T0_body           % debe ser ~0 %[output:358c6a4d]
T0 = T0_body;                % usamos la versión body como referencia

%% (2d) Construir T_sd(t) usando la trayectoria del dibujo

% Aquí asumimos que ya tienes en el workspace:
%   t       -> vector de tiempo (de Step 1)
%   x_traj  -> x(t) en {b}
%   y_traj  -> y(t) en {b}

N   = length(t);
Tsd = zeros(4,4,N);

% Chequeo de la trayectoria en {b}
fprintf('geom start (b): (%.4f, %.4f)\n', x_traj(1),  y_traj(1)); %[output:1419c500]
fprintf('geom final (b): (%.4f, %.4f)\n\n', x_traj(end), y_traj(end)); %[output:9c965d8b]

for i = 1:N
    % posición deseada en el frame {b}
    pb = [x_traj(i); y_traj(i); 0];   % z = 0 en {b}

    % orientación deseada en {b} (sin rotación adicional)
    Rb = eye(3);

    % transformación deseada relativa Td (de {b} en home a {b} deseado)
    Td = [Rb, pb;
          0 0 0 1];

    % transformación total en el frame espacial {s}
    % T_sd(t) = T0 * Td(t)
    Tsd(:,:,i) = T0 * Td;
end

% Extraer p(t) = (x,y,z) en el frame {s}
xs = squeeze(Tsd(1,4,:));
ys = squeeze(Tsd(2,4,:));
zs = squeeze(Tsd(3,4,:));

% Chequeo en {s}
fprintf('start in {s}:  (%.4f, %.4f, %.4f)\n', xs(1), ys(1), zs(1)); %[output:6164dd79]
fprintf('final in {s}:  (%.4f, %.4f, %.4f)\n', xs(end), ys(end), zs(end)); %[output:80cae4b7]
fprintf('difference:    (%.4e, %.4e, %.4e)\n\n', ... %[output:group:86766182] %[output:10e3f65b]
        xs(end)-xs(1), ys(end)-ys(1), zs(end)-zs(1)); %[output:group:86766182] %[output:10e3f65b]

%% Plot 3D de la trayectoria en {s}

figure; %[output:7fc36c72]
plot3(xs, ys, zs, 'LineWidth', 1.5); hold on; grid on; %[output:7fc36c72]

plot3(xs(1),  ys(1),  zs(1),  'go', 'MarkerSize', 10, 'LineWidth', 2); %[output:7fc36c72]
plot3(xs(end),ys(end),zs(end),'rx', 'MarkerSize', 10, 'LineWidth', 2); %[output:7fc36c72]

title('End-effector trajectory in \{s\} frame'); %[output:7fc36c72]
xlabel('x (m)'); %[output:7fc36c72]
ylabel('y (m)'); %[output:7fc36c72]
zlabel('z (m)'); %[output:7fc36c72]
legend('Trajectory', 'Start', 'End', 'Location', 'bestoutside'); %[output:7fc36c72]
axis equal; %[output:7fc36c72]
view(3); %[output:7fc36c72]
hold off; %[output:7fc36c72]

%%
%[text] ## Step 3: Inverse Kinematics
%% STEP 3: Inverse Kinematics

% --- (3a) Prueba de IK en la configuración inicial (home) ---
initialguess = theta0;
Td_home = T0;    % queremos recuperar theta0 a partir de T0

[thetaSol0, success0] = ECE569_IKinBody(B, M, Td_home, initialguess, 1e-7, 1e-7);

if ~success0
    error('Error: Could not perform IK at home configuration.');
end

fprintf('Test IK at home:\n'); %[output:5fafc2c6]
disp(thetaSol0');   % debería ser muy cercano a theta0' %[output:6fc6a2d7]

% --- (3c) Perform IK at each time step ---

N = size(Tsd, 3);            % número de pasos de tiempo (coincide con length(t))

thetaAll = zeros(6, N);
thetaAll(:,1) = theta0;      % empezamos en la configuración inicial

eomg = 1e-8;                  % tolerancia en error rotacional
ev   = 1e-8;                  % tolerancia en error de traslación

f = waitbar(0, sprintf('Inverse Kinematics (1/%d) complete.', N));

for k = 2:N
    % initial guess = solución del paso anterior (suaviza el IK)
    initialguess = thetaAll(:, k-1);

    % T_d deseada en este instante (ya la calculaste en Step 2)
    Td = Tsd(:, :, k);

    % IK en cuerpo
    [thetaSol, success] = ECE569_IKinBody(B, M, Td, initialguess, eomg, ev);

    if ~success
        close(f);
        error('Error.\nCould not perform IK at index %d.', k);
    end

    thetaAll(:, k) = thetaSol;

    waitbar(k / N, f, sprintf('Inverse Kinematics (%d/%d) complete.', k, N));
end
close(f);

%% (3c) Verificar que los ángulos de junta no cambian bruscamente

dj = diff(thetaAll');    % primera diferencia en el tiempo
figure; %[output:60b11992]
plot(t(1:end-1), dj); %[output:60b11992]
title('First Order Difference in Joint Angles'); %[output:60b11992]
legend('J1','J2','J3','J4','J5','J6','Location','northeastoutside'); %[output:60b11992]
grid on; %[output:60b11992]
xlabel('time (s)'); %[output:60b11992]
ylabel('first order difference (rad)'); %[output:60b11992]

%% (3d) Verificar que la trayectoria de FK sigue la deseada

actualTsd = zeros(4,4,N);

for i = 1:N
    % Forward kinematics en el marco espacial {s}
    actualTsd(:,:,i) = ECE569_FKinSpace(M, S, thetaAll(:, i));
end

% Extraer p(t) = (x,y,z)
xs = squeeze(actualTsd(1,4,:));
ys = squeeze(actualTsd(2,4,:));
zs = squeeze(actualTsd(3,4,:));

figure; %[output:6d20940b]
plot3(xs, ys, zs, 'LineWidth', 1); hold on; %[output:6d20940b]
title('Verified Trajectory in \{s\} frame'); %[output:6d20940b]
xlabel('x (m)'); %[output:6d20940b]
ylabel('y (m)'); %[output:6d20940b]
zlabel('z (m)'); %[output:6d20940b]
plot3(xs(1),  ys(1),  zs(1),  'go', 'MarkerSize', 10, 'LineWidth', 2);   % inicio %[output:6d20940b]
plot3(xs(end),ys(end),zs(end),'rx', 'MarkerSize', 10, 'LineWidth', 2);   % final %[output:6d20940b]
legend('Trajectory', 'Start', 'End', 'Location', 'best'); %[output:6d20940b]
grid on; axis equal; %[output:6d20940b]
hold off; %[output:6d20940b]

%% (3e) Verificar que no se entra en una singularidad (det Jacobiano de cuerpo)

body_dets = zeros(N,1);

for i = 1:N
    Jb = ECE569_JacobianBody(B, thetaAll(:, i));
    body_dets(i) = det(Jb);
end

figure; %[output:4eba315a]
plot(t, body_dets, 'LineWidth', 1.5); %[output:4eba315a]
title('Manipulability (determinant of body Jacobian)'); %[output:4eba315a]
grid on; %[output:4eba315a]
xlabel('time (s)'); %[output:4eba315a]
ylabel('det(J_B)'); %[output:4eba315a]

%% (3f) Guardar a CSV para el robot real

% puedes jugar con encender/apagar LEDs
led = ones(N,1);

% vector de salida: tiempo + 6 ángulos + LED
data = [t' thetaAll' led];

% TODO: cambia el nombre al de tu Purdue ID
writematrix(data, 'ecorream_bonus.csv');
fprintf('Se guardó el archivo ecorream_bonus.csv con %d samples.\n', N); %[output:378de848]


